/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeMultiply_StandardMultiplication() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 0.0, 3.0, 0.0, 5.0});
        RealVector v2 = new ArrayRealVector(new double[]{2.0, 10.0, 4.0, 20.0, 0.0});

        // Expected: [1*2, 0*10, 3*4, 0*20, 5*0] = [2, 0, 12, 0, 0]
        // Note: OpenMapRealVector is sparse, so it only stores non-zero entries.
        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(2.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(12.0, result.getEntry(2), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(3), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(4), EPSILON);
    }

