    @Test
    public void testEbeMultiply_SparseToDense() {
        // v1 is sparse
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 1.0);
        v1.setEntry(2, 2.0);

        // v2 is dense
        RealVector v2 = new ArrayRealVector(new double[]{5.0, 5.0, 5.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(10.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeMultiply_WithNaN() {
        // Testing the MATH-803 edge case mentioned in comments:
        // If this[i] == 0 and v[i] == NaN, the result should be NaN.
        // However, the current implementation provided in the prompt 
        // ONLY iterates over non-zero entries of 'this'.
        // If 'this' has a 0 at index i, index i is never visited in the loop.
        // Therefore, result[i] remains 0.0 (the default).

        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 0.0); // Explicitly zero
        v1.setEntry(1, 1.0); // Non-zero

        RealVector v2 = new ArrayRealVector(new double[]{Double.NaN, 2.0, 3.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // Based on the provided code logic:
        // iter only visits index 1. res[1] = 1.0 * 2.0 = 2.0.
        // res[0] remains 0.0 because it was never in the iterator.
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(2.0, result.getEntry(1), EPSILON);
    }

