        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 0.0); 
        v1.setEntry(1, 1.0);

        RealVector v2 = new ArrayRealVector(new double[]{Double.POSITIVE_INFINITY, 2.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // Based on provided loop: res[0] stays 0.0
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(2.0, result.getEntry(1), EPSILON);
    }

